import pandas as pd

def lagged_ic(signal, fwd, lags):
    out = {}
    for k in lags:
        old = signal.shift(k)            # row t holds the signal from k rows earlier
        out[k] = round(float(rank_ic(old, fwd).mean()), 4)
    return pd.Series(out)
